<?php use App\Core\Security;$baseUrl=rtrim((require BASE_PATH.'/config/app.php')['url'],'/');$escape=static fn(mixed $v):string=>Security::escape((string)$v);$notifications=is_array($notifications??null)?$notifications:[];$message=$message??null;?>
<section class="dashboard-page"><div class="dashboard-topbar"><button class="dashboard-menu-toggle" type="button" data-dashboard-toggle aria-expanded="false" aria-controls="dashboard-sidebar" aria-label="Open dashboard menu"><span></span><span></span><span></span></button><div class="dashboard-breadcrumb"><a href="<?=$escape($baseUrl)?>/dashboard">Workspace</a><i>/</i><strong>Notifications</strong></div></div><header class="dashboard-heading"><div><p class="eyebrow">ACADEMY UPDATES</p><h1>My notifications</h1><p>Announcements and private conversations from the Academy.</p></div></header><?php if($message):?><div class="admin-alert admin-alert-success" role="status"><?=$escape($message)?></div><?php endif;?>
<?php if($notifications===[]):?><section class="dashboard-panel"><div class="dashboard-empty"><div><h2>You are all caught up</h2><p>New Academy announcements will appear here.</p></div></div></section><?php else:?><section class="notification-list"><?php foreach($notifications as $n):?><a class="dashboard-panel notification-student-card <?=$n['read_at']===null?'is-unread':''?>" href="<?=$escape($baseUrl)?>/notifications/view?notification_id=<?=(int)$n['id']?>"><span class="notification-unread-dot" aria-hidden="true"></span><div><p class="eyebrow"><?=$n['read_at']===null?'NEW ANNOUNCEMENT':'ACADEMY UPDATE'?> · <?=$escape(date('M j, Y',strtotime($n['published_at'])))?></p><h2><?=$escape($n['title'])?></h2><p><?=$escape(mb_strimwidth($n['body'],0,240,'…'))?></p><span class="dashboard-inline-link">Read and reply →</span></div></a><?php endforeach;?></section><?php endif;?></section>
